insert into public.quiz_categories (id, name, description, icon, color, sort_order) values ('virus', '病毒', '病毒学专门题库', '🦠', '#2E7D32', 1);
insert into public.quiz_chapters (id, category_id, name, description, sort_order) values ('hepatitis_virus', 'virus', '肝炎病毒', '肝炎病毒相关题目', 1);
insert into public.quiz_chapters (id, category_id, name, description, sort_order) values ('respiratory_virus', 'virus', '呼吸道病毒', '呼吸道病毒与常见肠道病毒相关题目', 2);
insert into public.quiz_chapters (id, category_id, name, description, sort_order) values ('herpes_virus', 'virus', '疱疹病毒', '人疱疹病毒相关题目', 3);
insert into public.quiz_chapters (id, category_id, name, description, sort_order) values ('retrovirus', 'virus', '逆转录病毒', 'HIV与HTLV相关题目', 4);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_1', 'virus', 'hepatitis_virus', '下列哪一种肝炎病毒属于DNA病毒？', '{"a":"HAV","b":"HBV","c":"HCV","d":"HEV"}'::jsonb, '"b"'::jsonb, 'HBV是五型肝炎病毒里唯一的DNA病毒，为“部分双链环状DNA”。其余HAV、HCV、HDV、HEV均为RNA病毒。', 1);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_2', 'virus', 'hepatitis_virus', '下列哪组肝炎病毒均通过粪-口途径传播？', '{"a":"HBV、HCV","b":"HAV、HEV","c":"HBV、HDV","d":"HCV、HEV"}'::jsonb, '"b"'::jsonb, 'HAV和HEV都经粪-口传播，特点是无包膜、急性感染、不慢性化。', 2);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_3', 'virus', 'hepatitis_virus', 'HAV的核酸类型是：', '{"a":"双链DNA","b":"单负链RNA","c":"单正链RNA","d":"环形RNA"}'::jsonb, '"c"'::jsonb, 'HAV为单正链RNA病毒。 记忆：HAV、HCV、HEV都是“+RNA”。', 3);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_4', 'virus', 'hepatitis_virus', '下列哪种肝炎病毒属于缺陷病毒？', '{"a":"HAV","b":"HBV","c":"HCV","d":"HDV"}'::jsonb, '"d"'::jsonb, 'HDV是缺陷病毒，必须依赖HBV提供HBsAg才能复制和装配。', 4);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_5', 'virus', 'hepatitis_virus', '下列关于HAV的描述，正确的是：', '{"a":"有包膜","b":"易形成慢性感染","c":"仅有一个血清型","d":"主要经血液传播"}'::jsonb, '"c"'::jsonb, 'HAV只有一个血清型，因此疫苗保护效果稳定。HAV无包膜，经粪-口传播，不慢性化。', 5);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_6', 'virus', 'hepatitis_virus', 'HAV对下列哪种环境耐受性较强？', '{"a":"高温","b":"强碱","c":"酸性环境","d":"紫外线"}'::jsonb, '"c"'::jsonb, 'HAV耐酸，pH1环境仍可存活，因此适合经胃肠道传播。', 6);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_7', 'virus', 'hepatitis_virus', 'HAV感染后最主要的传播媒介是：', '{"a":"血液","b":"精液","c":"粪便污染的水和食物","d":"飞沫"}'::jsonb, '"c"'::jsonb, 'HAV主要通过被粪便污染的水、食物传播，尤其贝类海产品。', 7);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_8', 'virus', 'hepatitis_virus', 'HAV感染后最具有诊断意义的抗体是：', '{"a":"抗-HAV IgG","b":"抗-HAV IgM","c":"抗-HBs","d":"抗-HBc"}'::jsonb, '"b"'::jsonb, '抗-HAV IgM提示近期急性感染。IgG提示既往感染或免疫。', 8);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_9', 'virus', 'hepatitis_virus', 'HAV最主要的致病机制是：', '{"a":"病毒直接溶解肝细胞","b":"细菌毒素损伤","c":"免疫损伤","d":"血栓形成"}'::jsonb, '"c"'::jsonb, 'HAV肝损伤主要由免疫反应导致，而不是病毒直接细胞毒作用。', 9);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_10', 'virus', 'hepatitis_virus', '关于HAV感染特点，错误的是：', '{"a":"可出现隐性感染","b":"可形成慢性携带状态","c":"感染后可获得终身免疫","d":"多数预后良好"}'::jsonb, '"b"'::jsonb, 'HAV不会形成慢性感染或慢性携带状态。', 10);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_11', 'virus', 'hepatitis_virus', 'HEV感染最危险的人群是：', '{"a":"儿童","b":"老年男性","c":"孕妇","d":"糖尿病患者"}'::jsonb, '"c"'::jsonb, 'HEV对孕妇尤其危险，死亡率可高达20%。', 11);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_12', 'virus', 'hepatitis_virus', 'HEV的主要传播途径是：', '{"a":"血液传播","b":"虫媒传播","c":"粪-口传播","d":"性传播"}'::jsonb, '"c"'::jsonb, 'HEV与HAV一样，经粪-口传播。', 12);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_13', 'virus', 'hepatitis_virus', '下列关于HBV结构的描述，正确的是：', '{"a":"无包膜RNA病毒","b":"有包膜DNA病毒","c":"有包膜单负链RNA病毒","d":"无包膜DNA病毒"}'::jsonb, '"b"'::jsonb, 'HBV是有包膜DNA病毒。', 13);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_14', 'virus', 'hepatitis_virus', 'HBV完整具有感染性的病毒颗粒称为：', '{"a":"Delta颗粒","b":"Dane颗粒","c":"小球形颗粒","d":"管状颗粒"}'::jsonb, '"b"'::jsonb, 'Dane颗粒是完整有感染性的HBV颗粒，直径约42nm。', 14);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_15', 'virus', 'hepatitis_virus', 'HBV小球形颗粒的特点是：', '{"a":"含完整DNA","b":"有感染性","c":"仅由HBsAg组成","d":"含HBcAg"}'::jsonb, '"c"'::jsonb, '小球形颗粒和管状颗粒主要由HBsAg组成，无核心、无感染性。', 15);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_16', 'virus', 'hepatitis_virus', 'HBV复制过程中最关键的酶是：', '{"a":"RNA聚合酶","b":"DNA连接酶","c":"逆转录酶","d":"蛋白酶"}'::jsonb, '"c"'::jsonb, 'HBV DNA聚合酶具有逆转录酶活性，是复制关键。', 16);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_17', 'virus', 'hepatitis_virus', 'HBV进入肝细胞依赖的受体是：', '{"a":"CD4","b":"ACE2","c":"NTCP","d":"CCR5"}'::jsonb, '"c"'::jsonb, 'HBV通过NTCP受体进入肝细胞。', 17);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_18', 'virus', 'hepatitis_virus', 'HBV复制过程中形成稳定存在模板的是：', '{"a":"pgRNA","b":"HBsAg","c":"cccDNA","d":"HBeAg"}'::jsonb, '"c"'::jsonb, 'cccDNA是HBV在细胞核内形成的稳定模板，是慢性感染难清除的重要原因。', 18);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_19', 'virus', 'hepatitis_virus', 'HBV的前基因组RNA（pgRNA）主要作用是：', '{"a":"编码脂多糖","b":"作为逆转录模板","c":"抑制补体","d":"激活溶酶体"}'::jsonb, '"b"'::jsonb, 'pgRNA既是mRNA，也是逆转录生成DNA的模板。', 19);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_20', 'virus', 'hepatitis_virus', 'HBV病毒DNA复制的直接模板是：', '{"a":"cccDNA","b":"pgRNA","c":"HBsAg","d":"HBcAg"}'::jsonb, '"b"'::jsonb, 'HBV DNA复制直接以pgRNA为模板进行逆转录。', 20);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_21', 'virus', 'hepatitis_virus', '下列哪项提示HBV复制活跃、传染性强？', '{"a":"抗-HBs阳性","b":"抗-HBe阳性","c":"HBeAg阳性","d":"抗-HBc IgG阳性"}'::jsonb, '"c"'::jsonb, 'HBeAg阳性提示病毒复制活跃、传染性强。', 21);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_22', 'virus', 'hepatitis_virus', '下列哪项提示机体已具有乙肝免疫力？', '{"a":"HBsAg阳性","b":"抗-HBs阳性","c":"HBeAg阳性","d":"HBV DNA阳性"}'::jsonb, '"b"'::jsonb, '抗-HBs阳性说明机体已有保护性免疫。', 22);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_23', 'virus', 'hepatitis_virus', 'HBV窗口期最重要的检测指标是：', '{"a":"HBsAg","b":"抗-HBs","c":"抗-HBc IgM","d":"HBeAg"}'::jsonb, '"c"'::jsonb, '窗口期只有抗-HBc IgM能检测到。 窗口期特点：HBsAg消失，但抗-HBs尚未出现。', 23);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_24', 'virus', 'hepatitis_virus', 'HBV相关肾炎主要属于：', '{"a":"I型变态反应","b":"II型变态反应","c":"III型变态反应","d":"IV型变态反应"}'::jsonb, '"c"'::jsonb, 'HBV相关肾炎属于III型变态反应，即免疫复合物沉积。', 24);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_25', 'virus', 'hepatitis_virus', 'HBV感染导致肝细胞损伤最主要依赖：', '{"a":"病毒毒素","b":"CTL细胞免疫","c":"中性粒细胞","d":"补体直接裂解"}'::jsonb, '"b"'::jsonb, 'HBV主要通过CTL介导的细胞免疫损伤肝细胞。', 25);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_26', 'virus', 'hepatitis_virus', '新生儿感染HBV后容易慢性化，主要因为：', '{"a":"病毒毒力增强","b":"肝脏代谢弱","c":"免疫耐受","d":"补体缺乏"}'::jsonb, '"c"'::jsonb, '新生儿免疫系统不成熟，容易形成免疫耐受，因此慢性化率极高。', 26);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_27', 'virus', 'hepatitis_virus', 'HBV疫苗属于：', '{"a":"灭活疫苗","b":"减毒活疫苗","c":"基因工程疫苗","d":"核酸疫苗"}'::jsonb, '"c"'::jsonb, '乙肝疫苗是酵母重组基因工程疫苗。', 27);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_28', 'virus', 'hepatitis_virus', '医护人员HBV暴露后紧急预防应使用：', '{"a":"青霉素","b":"干扰素","c":"HBIG","d":"阿昔洛韦"}'::jsonb, '"c"'::jsonb, 'HBIG（乙肝高效价免疫球蛋白）用于暴露后紧急预防。', 28);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_29', 'virus', 'hepatitis_virus', 'HCV属于：', '{"a":"无包膜DNA病毒","b":"有包膜RNA病毒","c":"双链RNA病毒","d":"缺陷病毒"}'::jsonb, '"b"'::jsonb, 'HCV属于有包膜单正链RNA病毒，黄病毒科。', 29);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_30', 'virus', 'hepatitis_virus', 'HCV最主要的传播途径是：', '{"a":"呼吸道传播","b":"粪-口传播","c":"血液传播","d":"虫媒传播"}'::jsonb, '"c"'::jsonb, 'HCV主要通过血液传播。', 30);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_31', 'virus', 'hepatitis_virus', 'HCV感染后最常见的结局是：', '{"a":"完全清除","b":"急性暴发性肝炎","c":"慢性感染","d":"终身隐性感染但无肝损伤"}'::jsonb, '"c"'::jsonb, 'HCV最容易慢性化，约70%转为持续性感染。', 31);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_32', 'virus', 'hepatitis_virus', 'HCV实验室确诊的金标准是：', '{"a":"ELISA检测抗体","b":"RT-PCR检测RNA","c":"肝酶检测","d":"血常规"}'::jsonb, '"b"'::jsonb, 'RT-PCR检测HCV RNA是确诊金标准。', 32);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_33', 'virus', 'hepatitis_virus', 'HCV窗口期时最容易出现的结果是：', '{"a":"RNA阴性、抗体阳性","b":"RNA阳性、抗体阴性","c":"RNA阴性、抗体阴性","d":"RNA阳性、HBsAg阳性"}'::jsonb, '"b"'::jsonb, 'HCV窗口期特点：RNA已阳性，但抗体尚未出现，因此ELISA可能漏检。', 33);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_34', 'virus', 'hepatitis_virus', 'HDV必须依赖哪种病毒辅助复制？', '{"a":"HAV","b":"HBV","c":"HCV","d":"HEV"}'::jsonb, '"b"'::jsonb, 'HDV必须依赖HBV。', 34);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_35', 'virus', 'hepatitis_virus', 'HDV包膜来源于：', '{"a":"HCV包膜蛋白","b":"自身编码蛋白","c":"HBsAg","d":"HBcAg"}'::jsonb, '"c"'::jsonb, 'HDV包膜来源于HBsAg。', 35);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_36', 'virus', 'hepatitis_virus', 'HDV与HBV同时感染时最容易引起：', '{"a":"慢性携带","b":"爆发性肝炎","c":"无症状感染","d":"肠炎"}'::jsonb, '"b"'::jsonb, 'HBV与HDV同时感染容易引起严重急性爆发性肝炎。', 36);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_37', 'virus', 'hepatitis_virus', '预防HDV最有效的方法是：', '{"a":"接种HAV疫苗","b":"接种HBV疫苗","c":"注射抗生素","d":"接种HCV疫苗"}'::jsonb, '"b"'::jsonb, '预防HBV即可预防HDV，因为HDV离不开HBV。', 37);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_38', 'virus', 'hepatitis_virus', '下列哪种肝炎病毒最容易慢性化？', '{"a":"HAV","b":"HEV","c":"HCV","d":"HDV同时感染"}'::jsonb, '"c"'::jsonb, 'HCV最容易慢性化，且隐匿性强。', 38);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_39', 'virus', 'hepatitis_virus', '关于五型肝炎病毒共同点，正确的是：', '{"a":"都有包膜","b":"都可慢性化","c":"都以肝脏为主要靶器官","d":"都通过血液传播"}'::jsonb, '"c"'::jsonb, '五种肝炎病毒共同点：主要靶器官均为肝脏。', 39);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('hepatitis_virus_40', 'virus', 'hepatitis_virus', '下列关于肝炎病毒的说法，错误的是：', '{"a":"HAV和HEV主要经粪-口传播","b":"HBV可通过母婴传播","c":"HCV已有广泛应用疫苗","d":"HDV依赖HBV存在"}'::jsonb, '"c"'::jsonb, '目前尚无广泛应用的HCV疫苗，因此这项错误。', 40);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('respiratory_virus_1', 'virus', 'respiratory_virus', '呼吸道病毒最常见的入侵和增殖部位是：', '{"a":"皮肤角质层","b":"呼吸道黏膜上皮","c":"肝细胞","d":"神经节细胞"}'::jsonb, '"b"'::jsonb, '材料指出呼吸道病毒经呼吸道入侵，并主要在黏膜上皮增殖，可导致约90%的呼吸道感染。', 1);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('respiratory_virus_2', 'virus', 'respiratory_virus', '冠状病毒的基因组类型是：', '{"a":"分节段双链DNA","b":"线性不分节段单正链RNA","c":"环状单负链RNA","d":"双链RNA"}'::jsonb, '"b"'::jsonb, '冠状病毒基因组为线性、不分节段的单正链RNA，长度约27-32 kb。', 2);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('respiratory_virus_3', 'virus', 'respiratory_virus', '冠状病毒包膜表面的主要突起结构称为：', '{"a":"鞭毛","b":"菌毛","c":"纤突或冠突","d":"芽胞"}'::jsonb, '"c"'::jsonb, '冠状病毒为有包膜病毒，包膜上有稀疏均匀的纤突/冠突，外观类似日冕。', 3);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('respiratory_virus_4', 'virus', 'respiratory_virus', '下列哪一项不是冠状病毒的主要结构蛋白？', '{"a":"S蛋白","b":"E蛋白","c":"M蛋白","d":"HBsAg"}'::jsonb, '"d"'::jsonb, '冠状病毒主要结构蛋白包括刺突蛋白S、包膜蛋白E、膜蛋白M和核衣壳蛋白N；HBsAg属于乙肝病毒。', 4);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('respiratory_virus_5', 'virus', 'respiratory_virus', 'SARS病毒主要可通过哪种方式传播？', '{"a":"粪-口传播","b":"气溶胶和飞沫传播","c":"虫媒传播","d":"经胎盘传播"}'::jsonb, '"b"'::jsonb, '材料列出SARS病毒通过气溶胶、飞沫传播，表现为发热、干咳、胸闷等。', 5);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('respiratory_virus_6', 'virus', 'respiratory_virus', '流感病毒分型主要依据哪两类蛋白的抗原性差异？', '{"a":"S蛋白和N蛋白","b":"NP和M蛋白","c":"GP120和GP41","d":"VP1和VP4"}'::jsonb, '"b"'::jsonb, '流感病毒分型主要依据核蛋白NP和基质蛋白M1/M2的抗原性差异，分为甲、乙、丙三型。', 6);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('respiratory_virus_7', 'virus', 'respiratory_virus', '最易发生抗原漂移和抗原转换并导致全球大流行的是：', '{"a":"甲型流感病毒","b":"乙型流感病毒","c":"丙型流感病毒","d":"腺病毒"}'::jsonb, '"a"'::jsonb, '甲型流感病毒宿主范围广，易发生抗原漂移和抗原转换，可引起全球大流行。', 7);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('respiratory_virus_8', 'virus', 'respiratory_virus', '流感病毒包膜上负责水解神经氨酸并帮助病毒释放的是：', '{"a":"血凝素HA","b":"神经氨酸酶NA","c":"基质蛋白M1","d":"核蛋白NP"}'::jsonb, '"b"'::jsonb, '神经氨酸酶NA可水解细胞表面神经氨酸，促进子代病毒释放，同时具有抗原性。', 8);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('respiratory_virus_9', 'virus', 'respiratory_virus', '流感病毒血凝素HA的主要功能不包括：', '{"a":"介导吸附和穿入","b":"与红细胞结合","c":"作为分型依据之一","d":"整合入宿主染色体"}'::jsonb, '"d"'::jsonb, 'HA介导吸附穿入、与红细胞结合并具有抗原性；整合入宿主染色体不是流感病毒复制特点。', 9);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('respiratory_virus_10', 'virus', 'respiratory_virus', '流感病毒抗原漂移的特点是：', '{"a":"不同流感病毒基因重配导致质变","b":"小变异，可引起小规模流行","c":"只发生于DNA病毒","d":"必然导致全球大流行"}'::jsonb, '"b"'::jsonb, '抗原漂移属于量变，常导致小规模或季节性流行；抗原转换才是重配导致的质变。', 10);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('respiratory_virus_11', 'virus', 'respiratory_virus', '流感病毒抗原转换的机制和后果是：', '{"a":"点突变，小规模流行","b":"不同流感病毒重配，可能大规模流行","c":"包膜脱落，感染力消失","d":"DNA整合，形成潜伏感染"}'::jsonb, '"b"'::jsonb, '抗原转换是不同流感病毒发生基因重配造成质变，可导致大规模流行。', 11);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('respiratory_virus_12', 'virus', 'respiratory_virus', '流感病毒常用的培养部位是鸡胚的：', '{"a":"羊膜腔","b":"卵黄囊","c":"尿囊膜外层","d":"绒毛尿囊膜"}'::jsonb, '"a"'::jsonb, '材料中列出流感病毒可用鸡胚羊膜腔培养。', 12);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('respiratory_virus_13', 'virus', 'respiratory_virus', '麻疹病毒感染的典型致病过程包括：', '{"a":"一次病毒血症后立即潜伏于神经节","b":"两次病毒血症后出现典型症状","c":"先整合再出芽","d":"仅局部复制不入血"}'::jsonb, '"b"'::jsonb, '麻疹病毒经呼吸道入侵后经历两次病毒血症，随后出现发热、科氏斑、皮疹等典型表现。', 13);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('respiratory_virus_14', 'virus', 'respiratory_virus', '麻疹的特征性口腔黏膜表现是：', '{"a":"鹅口疮","b":"科氏斑","c":"杨梅舌","d":"白斑"}'::jsonb, '"b"'::jsonb, '麻疹可出现口腔黏膜科氏斑，并伴高热、畏光、咳嗽、鼻炎、结膜炎和红色斑丘疹。', 14);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('respiratory_virus_15', 'virus', 'respiratory_virus', '麻疹病毒感染后可能发生的迟发性严重并发症是：', '{"a":"亚急性硬化性全脑炎","b":"带状疱疹","c":"卡波西肉瘤","d":"巨细胞包含体病"}'::jsonb, '"a"'::jsonb, '麻疹病毒可并发亚急性硬化性全脑炎（SSPE），属于少见但严重的迟发性中枢神经系统并发症。', 15);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('respiratory_virus_16', 'virus', 'respiratory_virus', '腮腺炎病毒感染后的重要并发症不包括：', '{"a":"睾丸炎","b":"卵巢炎","c":"可能导致不育","d":"肝细胞癌"}'::jsonb, '"d"'::jsonb, '腮腺炎病毒可并发睾丸炎、卵巢炎，严重时可影响生育；肝细胞癌不是其典型并发症。', 16);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('respiratory_virus_17', 'virus', 'respiratory_virus', '婴幼儿致死性急性呼吸道感染的重要病原体是：', '{"a":"呼吸道合胞病毒","b":"EB病毒","c":"HBV","d":"HTLV-1"}'::jsonb, '"a"'::jsonb, '呼吸道合胞病毒是婴幼儿致死性急性呼吸道感染的主要病原体，可致细支气管炎和肺炎。', 17);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('respiratory_virus_18', 'virus', 'respiratory_virus', '关于呼吸道合胞病毒，下列说法正确的是：', '{"a":"感染后终身免疫，不再感染","b":"目前已有常规疫苗","c":"可局部增殖并反复感染","d":"主要导致成人肝炎"}'::jsonb, '"c"'::jsonb, '材料指出RSV可院内感染，病毒局部增殖，易反复感染，目前无疫苗。', 18);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('respiratory_virus_19', 'virus', 'respiratory_virus', '风疹病毒最重要的公共卫生意义是：', '{"a":"导致乙肝慢性化","b":"与先天性风疹综合征相关","c":"引起脊髓前角细胞损伤","d":"导致成人T细胞白血病"}'::jsonb, '"b"'::jsonb, '风疹与出生缺陷密切相关，先天性风疹综合征可表现为白内障、先天性心脏病、耳聋等。', 19);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('respiratory_virus_20', 'virus', 'respiratory_virus', '风疹感染的典型表现不包括：', '{"a":"发热","b":"麻疹样出疹","c":"耳后或枕后淋巴结肿大","d":"Dane颗粒形成"}'::jsonb, '"d"'::jsonb, '风疹表现包括发热、麻疹样出疹、耳后/枕后淋巴结肿大；Dane颗粒属于HBV。', 20);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('respiratory_virus_21', 'virus', 'respiratory_virus', '腺病毒的基本结构特点是：', '{"a":"有包膜单负链RNA病毒","b":"无包膜双链DNA病毒，二十面体对称","c":"缺陷RNA病毒","d":"有包膜逆转录病毒"}'::jsonb, '"b"'::jsonb, '腺病毒为不分节双链DNA无包膜病毒，二十面体对称，具有纤维刺突。', 21);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('respiratory_virus_22', 'virus', 'respiratory_virus', '脊髓灰质炎病毒的基因组和包膜特点是：', '{"a":"双链DNA，有包膜","b":"单正链RNA，无包膜","c":"分节段RNA，有包膜","d":"环状RNA，有HBsAg包膜"}'::jsonb, '"b"'::jsonb, '脊髓灰质炎病毒为球形、二十面体对称、无包膜的单正链RNA病毒。', 22);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('respiratory_virus_23', 'virus', 'respiratory_virus', '脊髓灰质炎病毒主要损伤的细胞是：', '{"a":"肝细胞","b":"脊髓前角运动细胞","c":"B淋巴细胞","d":"胃壁细胞"}'::jsonb, '"b"'::jsonb, '脊髓灰质炎病毒经粪口传播，可感染脊髓前角运动细胞，导致弛缓性麻痹。', 23);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('respiratory_virus_24', 'virus', 'respiratory_virus', '麻痹性脊髓灰质炎的典型特点是：', '{"a":"对称性痉挛性麻痹，感觉消失","b":"非对称弛缓性麻痹，感觉存在","c":"皮肤带状疱疹伴神经痛","d":"高热3天后热退疹出"}'::jsonb, '"b"'::jsonb, '麻痹性脊髓灰质炎表现为非对称弛缓性麻痹，感觉存在但运动能力受损。', 24);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('respiratory_virus_25', 'virus', 'respiratory_virus', '手足口病常见病原体是：', '{"a":"CoxA16和EV71","b":"HSV-1和HSV-2","c":"HIV-1和HIV-2","d":"HAV和HEV"}'::jsonb, '"a"'::jsonb, '手足口病主要由CoxA16、EV71等肠道病毒引起，学前儿童多见，EV71少数可致重症。', 25);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('herpes_virus_1', 'virus', 'herpes_virus', '人疱疹病毒的共同结构特点是：', '{"a":"无包膜RNA病毒","b":"有包膜双链线性DNA病毒","c":"无包膜双链RNA病毒","d":"有包膜单正链RNA病毒"}'::jsonb, '"b"'::jsonb, '人疱疹病毒为有包膜DNA病毒，表面有糖蛋白刺突，内含皮膜和衣壳，核心为双链线性DNA。', 1);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('herpes_virus_2', 'virus', 'herpes_virus', '疱疹病毒DNA复制主要发生在：', '{"a":"细胞核","b":"线粒体","c":"核糖体","d":"细胞膜外"}'::jsonb, '"a"'::jsonb, '疱疹病毒基因组大，编码多种蛋白，并拥有自身编码的DNA聚合酶，DNA复制在细胞核内进行。', 2);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('herpes_virus_3', 'virus', 'herpes_virus', '疱疹病毒裂解性感染时蛋白合成顺序是：', '{"a":"L、E、IE","b":"IE、E、L","c":"E、L、IE","d":"只合成L蛋白"}'::jsonb, '"b"'::jsonb, '裂解性感染中病毒按即刻早期蛋白IE、早期蛋白E、晚期蛋白L顺序合成，最终导致细胞裂解死亡。', 3);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('herpes_virus_4', 'virus', 'herpes_virus', '疱疹病毒潜伏感染时病毒基因组通常以哪种形式存在？', '{"a":"整合入线粒体DNA","b":"未整合附加体形式","c":"游离RNA片段","d":"蛋白质颗粒"}'::jsonb, '"b"'::jsonb, '潜伏感染时疱疹病毒基因组以未整合的附加体形式存在，不增殖，仅表达少量基因，可被诱因激活。', 4);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('herpes_virus_5', 'virus', 'herpes_virus', 'HSV-1主要引起的感染部位和疾病是：', '{"a":"腰部以上，如口唇疱疹和角膜炎","b":"仅生殖器疱疹","c":"仅肝炎","d":"肠道疱疹"}'::jsonb, '"a"'::jsonb, 'HSV-1主要引起腰部以上感染，如口唇疱疹、疱疹性角膜炎和脑炎；HSV-2多引起生殖器疱疹。', 5);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('herpes_virus_6', 'virus', 'herpes_virus', 'HSV-2常见潜伏部位是：', '{"a":"三叉神经节","b":"骶神经节","c":"脊髓前角","d":"肝细胞核"}'::jsonb, '"b"'::jsonb, 'HSV-2主要引起腰部以下生殖器疱疹，常潜伏于骶神经节。', 6);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('herpes_virus_7', 'virus', 'herpes_virus', 'HSV复发的常见诱因不包括：', '{"a":"紫外线","b":"发热","c":"压力和月经","d":"接种乙肝疫苗"}'::jsonb, '"d"'::jsonb, 'HSV可因紫外线、发热、压力、月经、免疫抑制等诱因复发；乙肝疫苗不是典型诱因。', 7);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('herpes_virus_8', 'virus', 'herpes_virus', '诊断HSV脑炎时最有价值的检测方法是：', '{"a":"脑脊液PCR检测核酸","b":"肥达反应","c":"外斐反应","d":"检测HBsAg"}'::jsonb, '"a"'::jsonb, 'HSV诊断可用直接荧光抗体检测皮肤刮片抗原，脑炎时脑脊液PCR检测核酸尤其重要。', 8);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('herpes_virus_9', 'virus', 'herpes_virus', '治疗严重HSV感染的首选药物是：', '{"a":"阿昔洛韦","b":"青霉素","c":"奥司他韦","d":"齐多夫定"}'::jsonb, '"a"'::jsonb, '阿昔洛韦为核苷类似物，是眼部感染、脑炎、免疫缺陷感染等严重HSV感染的首选药物。', 9);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('herpes_virus_10', 'virus', 'herpes_virus', 'VZV原发感染引起：', '{"a":"带状疱疹","b":"水痘","c":"鼻咽癌","d":"卡波西肉瘤"}'::jsonb, '"b"'::jsonb, '水痘-带状疱疹病毒原发感染引起水痘，复发感染引起带状疱疹。', 10);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('herpes_virus_11', 'virus', 'herpes_virus', '水痘皮疹“四世同堂”指的是：', '{"a":"斑丘疹、疱疹、结痂等不同阶段同时存在","b":"四种病毒同时感染","c":"四个神经节潜伏","d":"四类抗体同时阳性"}'::jsonb, '"a"'::jsonb, '水痘特征性皮疹为斑丘疹、疱疹、结痂等不同阶段同时存在，称“四世同堂”。', 11);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('herpes_virus_12', 'virus', 'herpes_virus', '带状疱疹的发生机制是：', '{"a":"VZV潜伏于脊髓后根神经节后再激活","b":"HSV-2整合于肝细胞","c":"EBV感染脊髓前角","d":"CMV经粪口传播"}'::jsonb, '"a"'::jsonb, 'VZV可潜伏于脊髓后根神经节，再激活后沿感觉神经下行至单侧皮肤，形成带状疱疹。', 12);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('herpes_virus_13', 'virus', 'herpes_virus', 'EB病毒传染性单核细胞增多症的常见传播方式是：', '{"a":"唾液传播","b":"虫媒传播","c":"粪口传播","d":"气溶胶传播为主"}'::jsonb, '"a"'::jsonb, 'EBV可经唾液传播，传染性单核细胞增多症又称“接吻病”，表现为发热、咽痛、淋巴结肿大等。', 13);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('herpes_virus_14', 'virus', 'herpes_virus', 'EB病毒相关肿瘤不包括：', '{"a":"Burkitt淋巴瘤","b":"鼻咽癌","c":"免疫缺陷相关淋巴增生性疾病","d":"成人T细胞白血病"}'::jsonb, '"d"'::jsonb, 'EBV与Burkitt淋巴瘤、鼻咽癌、免疫缺陷相关淋巴增生性疾病有关；成人T细胞白血病与HTLV-1有关。', 14);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('herpes_virus_15', 'virus', 'herpes_virus', 'EBV感染中阿昔洛韦通常无效的主要原因是：', '{"a":"EBV无胸苷激酶","b":"EBV无包膜","c":"EBV为RNA病毒","d":"EBV不进入细胞"}'::jsonb, '"a"'::jsonb, '材料指出EBV无特效抗病毒药，因EBV无胸苷激酶，阿昔洛韦无效，多为支持治疗。', 15);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('herpes_virus_16', 'virus', 'herpes_virus', 'CMV先天性感染最可能导致：', '{"a":"巨细胞包含体病","b":"麻痹性脊髓灰质炎","c":"甲型肝炎","d":"手足口病"}'::jsonb, '"a"'::jsonb, 'CMV可经胎盘感染胎儿，导致巨细胞包含体病，出现听力/视力障碍、中枢神经损伤、肝脾肿大等。', 16);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('herpes_virus_17', 'virus', 'herpes_virus', '治疗严重CMV感染常用药物是：', '{"a":"更昔洛韦","b":"阿昔洛韦","c":"奥司他韦","d":"干扰素联合AZT"}'::jsonb, '"a"'::jsonb, '严重CMV感染，尤其免疫缺陷、移植或新生儿感染，可使用更昔洛韦治疗。', 17);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('herpes_virus_18', 'virus', 'herpes_virus', 'HHV-6和HHV-7主要引起：', '{"a":"婴儿急疹","b":"鼻咽癌","c":"生殖器疱疹","d":"带状疱疹"}'::jsonb, '"a"'::jsonb, 'HHV-6和HHV-7可引起婴儿急疹，特点为高热3天后热退疹出。', 18);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('herpes_virus_19', 'virus', 'herpes_virus', 'HHV-8又称卡波西肉瘤相关病毒，主要见于：', '{"a":"AIDS患者","b":"新生儿常规感染","c":"乙肝疫苗接种者","d":"脊髓灰质炎患者"}'::jsonb, '"a"'::jsonb, 'HHV-8与卡波西肉瘤相关，常见于AIDS患者，可引起内皮细胞肿瘤。', 19);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('herpes_virus_20', 'virus', 'herpes_virus', '关于疱疹病毒感染特点，正确的是：', '{"a":"均不能潜伏","b":"可潜伏并在诱因下再激活","c":"均为无包膜病毒","d":"均对阿昔洛韦高度敏感"}'::jsonb, '"b"'::jsonb, '疱疹病毒的重要特点是可发生潜伏感染，并在紫外线、免疫抑制等诱因下再激活进入裂解期。', 20);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('retrovirus_1', 'virus', 'retrovirus', '逆转录病毒的核心复制特点是：', '{"a":"DNA直接复制为DNA","b":"RNA在逆转录酶作用下转为DNA","c":"蛋白质复制为RNA","d":"RNA不进入细胞"}'::jsonb, '"b"'::jsonb, '逆转录病毒为RNA病毒，其RNA在逆转录酶作用下生成DNA，是其核心生物学特征。', 1);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('retrovirus_2', 'virus', 'retrovirus', 'HIV双链DNA整合入宿主染色体后称为：', '{"a":"Dane颗粒","b":"前病毒","c":"cccDNA","d":"包涵体"}'::jsonb, '"b"'::jsonb, 'HIV RNA逆转录为双链DNA后进入细胞核，整合至宿主染色体形成前病毒。', 2);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('retrovirus_3', 'virus', 'retrovirus', '全球主要流行的HIV类型是：', '{"a":"HIV-1","b":"HIV-2","c":"HTLV-1","d":"HHV-8"}'::jsonb, '"a"'::jsonb, 'HIV包括HIV-1和HIV-2，其中HIV-1为全球主要流行类型，HIV-2主要在非洲局部流行。', 3);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('retrovirus_4', 'virus', 'retrovirus', 'HIV基因组的组成是：', '{"a":"一条双链DNA","b":"两条完全相同的单正链RNA","c":"分节段单负链RNA","d":"环状DNA"}'::jsonb, '"b"'::jsonb, 'HIV基因组由两条完全相同的单正链RNA组成。', 4);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('retrovirus_5', 'virus', 'retrovirus', 'HIV衣壳主要由哪种蛋白构成？', '{"a":"P24","b":"P17","c":"GP120","d":"GP41"}'::jsonb, '"a"'::jsonb, 'HIV衣壳由P24蛋白构成；P17为基质蛋白，GP120和GP41为包膜糖蛋白。', 5);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('retrovirus_6', 'virus', 'retrovirus', 'HIV包膜表面负责结合CD4的蛋白是：', '{"a":"GP120","b":"GP41","c":"P24","d":"P17"}'::jsonb, '"a"'::jsonb, 'GP120位于HIV包膜表面，先与CD4结合并发生构象变化，再结合辅助受体。', 6);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('retrovirus_7', 'virus', 'retrovirus', 'HIV介导膜融合的跨膜糖蛋白是：', '{"a":"GP41","b":"GP120","c":"Nef","d":"Tat"}'::jsonb, '"a"'::jsonb, 'GP41为跨膜糖蛋白，可插入宿主膜并介导病毒包膜与宿主细胞膜融合。', 7);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('retrovirus_8', 'virus', 'retrovirus', 'HIV pol基因编码的酶不包括：', '{"a":"逆转录酶","b":"蛋白酶","c":"整合酶","d":"神经氨酸酶"}'::jsonb, '"d"'::jsonb, 'HIV pol基因编码逆转录酶、蛋白酶和整合酶；神经氨酸酶是流感病毒的包膜蛋白。', 8);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('retrovirus_9', 'virus', 'retrovirus', 'HIV进入细胞所需主要受体和辅助受体是：', '{"a":"CD4及CCR5/CXCR4","b":"ACE2及TMPRSS2","c":"NTCP及HBsAg","d":"CD46及IgA"}'::jsonb, '"a"'::jsonb, 'HIV主要受体为CD4，辅助受体为CCR5或CXCR4。GP120结合CD4后再结合辅助受体。', 9);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('retrovirus_10', 'virus', 'retrovirus', 'HIV早期常见的巨噬细胞嗜性毒株主要使用的辅助受体是：', '{"a":"CCR5","b":"CXCR4","c":"NTCP","d":"CD21"}'::jsonb, '"a"'::jsonb, 'HIV感染初期多为巨噬细胞嗜性R5型，使用CCR5；后期可转为T细胞嗜性X4型，使用CXCR4。', 10);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('retrovirus_11', 'virus', 'retrovirus', 'HIV Nef蛋白的免疫逃逸作用是：', '{"a":"下调MHC I类分子表达","b":"水解神经氨酸","c":"编码HBsAg","d":"裂解红细胞"}'::jsonb, '"a"'::jsonb, 'Nef可下调细胞表面MHC I类分子表达，使感染细胞逃避CTL识别和杀伤。', 11);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('retrovirus_12', 'virus', 'retrovirus', 'AIDS期的典型免疫学指标是：', '{"a":"CD4+ T细胞<200/μL","b":"抗-HBs阳性","c":"血红蛋白升高","d":"IgA完全消失"}'::jsonb, '"a"'::jsonb, 'AIDS期CD4+ T细胞低于200/μL，免疫力极差，出现机会性感染、肿瘤和神经系统病变。', 12);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('retrovirus_13', 'virus', 'retrovirus', 'HIV抗体检测中，常用于初筛和确证的方法分别是：', '{"a":"ELISA和Western Blot","b":"PCR和肥达反应","c":"外斐反应和ELISA","d":"血凝试验和补体结合试验"}'::jsonb, '"a"'::jsonb, 'HIV抗体初筛常用ELISA，敏感性高；确诊常用Western Blot，特异性高。', 13);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('retrovirus_14', 'virus', 'retrovirus', 'HIV窗口期早期辅助诊断和疗效监测常用：', '{"a":"P24抗原或HIV RNA检测","b":"抗-HBs检测","c":"嗜异性抗体检测","d":"Tzanck试验"}'::jsonb, '"a"'::jsonb, 'P24抗原可早于抗体出现，HIV RNA检测可用于早期诊断、新生儿诊断及病毒载量疗效监测。', 14);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('retrovirus_15', 'virus', 'retrovirus', 'HTLV-1主要相关疾病是：', '{"a":"成人T淋巴细胞白血病/淋巴瘤","b":"传染性单核细胞增多症","c":"先天性风疹综合征","d":"麻痹性脊髓灰质炎"}'::jsonb, '"a"'::jsonb, 'HTLV-1感染T淋巴细胞，可经Tax等机制促进细胞转化，潜伏期长，少数感染者发生成人T淋巴细胞白血病/淋巴瘤。', 15);
insert into public.quiz_categories (id, name, description, icon, color, sort_order) values ('parasite', '寄生虫', '人体寄生虫学专门题库', '🪱', '#8E5A2D', 2);
insert into public.quiz_chapters (id, category_id, name, description, sort_order) values ('protozoa', 'parasite', '原虫', '医学原虫与机会致病原虫相关题目', 1);
insert into public.quiz_chapters (id, category_id, name, description, sort_order) values ('nematodes', 'parasite', '线虫', '常见人体寄生线虫相关题目', 2);
insert into public.quiz_chapters (id, category_id, name, description, sort_order) values ('cestodes', 'parasite', '绦虫', '常见人体寄生绦虫相关题目', 3);
insert into public.quiz_chapters (id, category_id, name, description, sort_order) values ('medical_arthropods', 'parasite', '医学节肢动物', '医学节肢动物及虫媒传播相关题目', 4);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_1', 'parasite', 'protozoa', '多数寄生原虫的基本生活型是：', '{"a":"虫卵","b":"滋养体","c":"成虫","d":"幼虫"}'::jsonb, '"b"'::jsonb, '滋养体是多数寄生原虫能运动、摄食和生殖的基本生活型；包囊或卵囊多与抵抗不良环境和传播有关。', 1);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_2', 'parasite', 'protozoa', '下列哪种运动方式不属于原虫常见运动方式？', '{"a":"伪足运动","b":"鞭毛运动","c":"纤毛运动","d":"节片蠕动"}'::jsonb, '"d"'::jsonb, '原虫常见运动方式包括伪足、鞭毛和纤毛运动；节片蠕动是绦虫节片等多细胞寄生虫相关表现。', 2);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_3', 'parasite', 'protozoa', '原虫无性生殖中最常见的方式是：', '{"a":"二分裂法","b":"结合生殖","c":"配子生殖","d":"产卵"}'::jsonb, '"a"'::jsonb, '寄生原虫最常见的无性增殖方式是二分裂法，胞核先分裂，随后胞质分裂形成两个子体。', 3);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_4', 'parasite', 'protozoa', '溶组织内阿米巴的感染阶段是：', '{"a":"四核成熟包囊","b":"含红细胞滋养体","c":"裂殖子","d":"前鞭毛体"}'::jsonb, '"a"'::jsonb, '溶组织内阿米巴的成熟四核包囊具有感染性，经粪口途径传播；滋养体主要负责侵袭和致病。', 4);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_5', 'parasite', 'protozoa', '溶组织内阿米巴肠病典型病变为：', '{"a":"环形溃疡","b":"烧瓶样溃疡","c":"干酪样坏死","d":"绒毛萎缩"}'::jsonb, '"b"'::jsonb, '肠阿米巴病多累及盲肠或阑尾，典型病灶为口小底大的烧瓶样溃疡。', 5);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_6', 'parasite', 'protozoa', '阿米巴痢疾典型粪便性状是：', '{"a":"米泔水样便","b":"暗红色果酱样便","c":"柏油样便","d":"白陶土样便"}'::jsonb, '"b"'::jsonb, '阿米巴痢疾常表现为暗红色果酱样、含粪质且有恶臭的粪便。', 6);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_7', 'parasite', 'protozoa', '急性阿米巴痢疾病原学检查首选标本处理是：', '{"a":"陈旧成形粪便碘染查虫卵","b":"新鲜脓血便生理盐水涂片查滋养体","c":"血培养查前鞭毛体","d":"肛周透明胶纸法"}'::jsonb, '"b"'::jsonb, '急性期应取新鲜脓血或粘液便，保温后用生理盐水涂片查活动滋养体。', 7);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_8', 'parasite', 'protozoa', '治疗肠内外侵袭性阿米巴病的首选药物是：', '{"a":"甲硝唑","b":"氯喹","c":"阿昔洛韦","d":"青霉素"}'::jsonb, '"a"'::jsonb, '甲硝唑可杀灭滋养体，是治疗急慢性肠阿米巴病和肠外阿米巴病的首选药物。', 8);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_9', 'parasite', 'protozoa', '杜氏利什曼原虫在人体内主要寄生于：', '{"a":"红细胞","b":"单核巨噬细胞","c":"小肠上皮细胞","d":"神经节细胞"}'::jsonb, '"b"'::jsonb, '杜氏利什曼原虫无鞭毛体寄生于单核巨噬细胞内，并在肝、脾、骨髓、淋巴结等处增殖。', 9);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_10', 'parasite', 'protozoa', '杜氏利什曼原虫的传播媒介主要是：', '{"a":"按蚊","b":"白蛉","c":"恙螨","d":"体虱"}'::jsonb, '"b"'::jsonb, '感染性白蛉叮咬时，前鞭毛体随唾液进入人体，是黑热病的重要传播方式。', 10);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_11', 'parasite', 'protozoa', '内脏利什曼病又称黑热病，其典型表现不包括：', '{"a":"长期不规则发热","b":"肝脾肿大","c":"全血细胞减少性贫血","d":"四肢对称性弛缓性麻痹"}'::jsonb, '"d"'::jsonb, '黑热病常见长期发热、消瘦、肝脾淋巴结肿大、高球蛋白血症和全血细胞减少；弛缓性麻痹不是其典型表现。', 11);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_12', 'parasite', 'protozoa', '黑热病病原学诊断最常用的穿刺部位是：', '{"a":"骨髓","b":"脑脊液","c":"胆汁","d":"尿液"}'::jsonb, '"a"'::jsonb, '骨髓穿刺涂片较常用，较安全且检出率高；脾穿刺虽检出率可高但风险较大。', 12);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_13', 'parasite', 'protozoa', '阴道毛滴虫的感染和致病阶段是：', '{"a":"包囊","b":"滋养体","c":"卵囊","d":"孢子"}'::jsonb, '"b"'::jsonb, '阴道毛滴虫生活史中只有滋养体阶段，滋养体既是繁殖阶段，也是感染和致病阶段。', 13);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_14', 'parasite', 'protozoa', '阴道毛滴虫主要寄生部位是：', '{"a":"女性阴道后穹隆","b":"肝细胞","c":"红细胞","d":"小肠绒毛"}'::jsonb, '"a"'::jsonb, '阴道毛滴虫主要寄生于女性阴道，尤其后穹隆部位；男性可寄生于尿道或前列腺。', 14);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_15', 'parasite', 'protozoa', '疟原虫生活史中，人和按蚊分别是：', '{"a":"人是终宿主，按蚊是中间宿主","b":"人是中间宿主，按蚊是终宿主","c":"二者均为终宿主","d":"二者均为中间宿主"}'::jsonb, '"b"'::jsonb, '疟原虫在人体内主要进行无性增殖，在按蚊体内进行有性生殖，因此人为中间宿主，按蚊为终宿主。', 15);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_16', 'parasite', 'protozoa', '间日疟和卵形疟复发的主要原因是：', '{"a":"红细胞内环状体持续分裂","b":"肝细胞内休眠子被激活","c":"虫卵在肠道重新孵化","d":"白蛉再次叮咬"}'::jsonb, '"b"'::jsonb, '间日疟和卵形疟可在肝细胞内形成休眠子，休眠子激活可导致复发；恶性疟和三日疟无休眠子。', 16);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_17', 'parasite', 'protozoa', '疟疾典型发作顺序是：', '{"a":"高热、寒颤、出汗","b":"寒颤、高热、出汗退热","c":"出汗、寒颤、高热","d":"皮疹、发热、结痂"}'::jsonb, '"b"'::jsonb, '疟疾典型发作包括寒颤、高热、出汗退热三个阶段，与红细胞周期性破裂释放裂殖子有关。', 17);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_18', 'parasite', 'protozoa', '疟疾病原学诊断的金标准是：', '{"a":"厚薄血膜染色镜检","b":"肛周拭子法","c":"饱和盐水浮聚法","d":"痰液抗酸染色"}'::jsonb, '"a"'::jsonb, '厚薄血膜染色镜检可直接发现疟原虫并辅助虫种鉴别，是疟疾病原学诊断金标准。', 18);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_19', 'parasite', 'protozoa', '恶性疟原虫外周血涂片常见的阶段是：', '{"a":"仅成熟裂殖体","b":"环状体和配子体","c":"包囊和滋养体","d":"虫卵和幼虫"}'::jsonb, '"b"'::jsonb, '恶性疟早期滋养体常隐匿于微血管，外周血多见环状体和配子体。', 19);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_20', 'parasite', 'protozoa', '刚地弓形虫的终宿主是：', '{"a":"犬","b":"猫科动物","c":"按蚊","d":"猪"}'::jsonb, '"b"'::jsonb, '猫科动物是弓形虫终宿主，可排出大量卵囊；人、猪等可作为中间宿主。', 20);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_21', 'parasite', 'protozoa', '刚地弓形虫先天性感染的传播方式是：', '{"a":"经胎盘垂直传播","b":"按蚊叮咬传播","c":"经皮肤钻入","d":"肛门-手-口传播"}'::jsonb, '"a"'::jsonb, '孕妇感染弓形虫后可经胎盘传播给胎儿，早期感染后果更严重。', 21);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_22', 'parasite', 'protozoa', '先天性弓形虫病典型四联症不包括：', '{"a":"脑积水","b":"大脑钙化","c":"小头畸形","d":"胆道蛔虫症"}'::jsonb, '"d"'::jsonb, '先天性弓形虫病典型四联症包括脑积水、大脑钙化、小头畸形和视网膜脉络膜炎。', 22);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_23', 'parasite', 'protozoa', '隐孢子虫主要寄生部位是：', '{"a":"小肠上皮细胞","b":"红细胞","c":"肝巨噬细胞","d":"骶神经节"}'::jsonb, '"a"'::jsonb, '隐孢子虫主要寄生于小肠上皮细胞，破坏微绒毛功能，引起消化吸收障碍和水样腹泻。', 23);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_24', 'parasite', 'protozoa', '隐孢子虫的感染阶段是：', '{"a":"卵囊","b":"成虫","c":"囊尾蚴","d":"丝状蚴"}'::jsonb, '"a"'::jsonb, '隐孢子虫感染阶段为卵囊。成熟卵囊含4个裸露子孢子。', 24);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_25', 'parasite', 'protozoa', '隐孢子虫卵囊中可引起自身重复感染的是：', '{"a":"薄壁卵囊","b":"厚壁卵囊","c":"未受精卵","d":"棘球蚴"}'::jsonb, '"a"'::jsonb, '薄壁卵囊约占20%，可在同一宿主体内引起自身重复感染；厚壁卵囊随粪便排出传播。', 25);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_26', 'parasite', 'protozoa', '关于隐孢子虫卵囊抵抗力，正确的是：', '{"a":"氯消毒容易杀灭","b":"对氯消毒抵抗力强","c":"干燥环境最适合长期存活","d":"只能在血液中存活"}'::jsonb, '"b"'::jsonb, '隐孢子虫卵囊对外界抵抗力强，氯消毒无效，氯化水中仍可存活数天。', 26);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_27', 'parasite', 'protozoa', 'AIDS患者隐孢子虫病最突出的临床问题是：', '{"a":"致死性慢性腹泻和脱水","b":"皮下游走性结节","c":"胆道蛔虫症","d":"带状疱疹"}'::jsonb, '"a"'::jsonb, '隐孢子虫是AIDS患者常见致死性腹泻原因，可导致大量水样便、脱水和电解质紊乱。', 27);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_28', 'parasite', 'protozoa', '隐孢子虫病治疗中最重要的是：', '{"a":"对症补液和纠正电解质紊乱","b":"立即手术摘除虫体","c":"单用青霉素","d":"接种乙肝疫苗"}'::jsonb, '"a"'::jsonb, '隐孢子虫病目前无理想抗虫药，治疗以补液、纠正电解质紊乱、加强营养和止泻等对症处理最重要。', 28);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_29', 'parasite', 'protozoa', '原虫机会致病性最容易出现在：', '{"a":"免疫功能受损者","b":"接种疫苗后短期内","c":"完全无暴露史者","d":"仅高原缺氧者"}'::jsonb, '"a"'::jsonb, '弓形虫、隐孢子虫、蓝氏贾第鞭毛虫等可在免疫抑制或AIDS等情况下致病性显著增强。', 29);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_30', 'parasite', 'protozoa', '溶组织内阿米巴最重要的传染源是：', '{"a":"排出四核包囊的慢性病人或无症状带虫者","b":"只排滋养体的急性患者","c":"按蚊成虫","d":"感染犬的皮屑"}'::jsonb, '"a"'::jsonb, '慢性病人和无症状带虫者可排出具有感染性的四核包囊，是阿米巴病最重要传染源。', 30);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_31', 'parasite', 'nematodes', '线虫虫体的基本形态特点是：', '{"a":"背腹扁平、分节带状","b":"圆柱形、两端尖、两侧对称","c":"单细胞、具伪足","d":"二十面体对称"}'::jsonb, '"b"'::jsonb, '线虫一般呈圆柱形、两端尖、两侧对称，雌雄异体且常雌大雄小。', 1);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_32', 'parasite', 'nematodes', '土源性线虫的生活史特点是：', '{"a":"必须经中间宿主发育","b":"无需中间宿主，直接发育","c":"必须在按蚊体内有性生殖","d":"只在犬体内完成"}'::jsonb, '"b"'::jsonb, '土源性线虫又称直接发育型线虫，无需中间宿主，常见于肠道寄生线虫。', 2);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_33', 'parasite', 'nematodes', '人体最大肠道线虫是：', '{"a":"似蚓蛔线虫","b":"蛲虫","c":"旋毛虫","d":"钩虫"}'::jsonb, '"a"'::jsonb, '似蚓蛔线虫即蛔虫，是人体最大的肠道线虫。', 3);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_34', 'parasite', 'nematodes', '蛔虫的感染阶段是：', '{"a":"含二期幼虫的感染期卵","b":"丝状蚴","c":"囊包幼虫","d":"微丝蚴"}'::jsonb, '"a"'::jsonb, '蛔虫受精卵排出时无感染性，在温暖潮湿土壤中发育约2周成为含二期幼虫的感染期卵。', 4);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_35', 'parasite', 'nematodes', '蛔虫成虫主要寄生于：', '{"a":"小肠","b":"肺泡","c":"肛周皮肤","d":"横纹肌"}'::jsonb, '"a"'::jsonb, '蛔虫成虫寄生于小肠；幼虫可经肝、右心、肺移行后再回到小肠发育。', 5);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_36', 'parasite', 'nematodes', '蛔虫病最常见、最重要的危害是：', '{"a":"并发症如胆道蛔虫症","b":"皮肤黑热病","c":"水样腹泻","d":"鼠疫传播"}'::jsonb, '"a"'::jsonb, '蛔虫危害以并发症为主，虫体钻孔和打结可导致胆道蛔虫症、肠梗阻、肠穿孔、胰腺炎等。', 6);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_37', 'parasite', 'nematodes', '蛔虫病病原学诊断首选方法是：', '{"a":"粪便直接涂片法","b":"骨髓穿刺","c":"肛周透明胶纸法","d":"厚薄血膜镜检"}'::jsonb, '"a"'::jsonb, '蛔虫病常用粪便直接涂片法查虫卵或虫体，三张涂片检出率可明显提高。', 7);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_38', 'parasite', 'nematodes', '钩虫的感染阶段是：', '{"a":"丝状蚴","b":"四核包囊","c":"裂头蚴","d":"卵囊"}'::jsonb, '"a"'::jsonb, '钩虫虫卵在土壤中发育为杆状蚴，再发育为具有感染性的丝状蚴。', 8);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_39', 'parasite', 'nematodes', '钩虫感染人体的主要方式是：', '{"a":"丝状蚴经皮肤钻入","b":"食入囊尾蚴","c":"白蛉叮咬","d":"接触猫粪中的卵囊"}'::jsonb, '"a"'::jsonb, '钩虫丝状蚴具有向温、向湿性，主要经皮肤钻入人体。', 9);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_40', 'parasite', 'nematodes', '钩虫病最主要的临床问题是：', '{"a":"缺铁性贫血","b":"脑积水","c":"肝包虫囊肿","d":"带状疱疹"}'::jsonb, '"a"'::jsonb, '钩虫成虫吸血、黏膜渗血和铁蛋白消耗导致缺铁性贫血，是钩虫病最主要表现。', 10);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_41', 'parasite', 'nematodes', '钩虫虫卵检查首选方法是：', '{"a":"饱和盐水浮聚法","b":"肛周拭子法","c":"血膜染色","d":"脑脊液PCR"}'::jsonb, '"a"'::jsonb, '钩虫病粪便查虫卵首选饱和盐水浮聚法，检出率高于直接涂片。', 11);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_42', 'parasite', 'nematodes', '十二指肠钩虫与美洲钩虫的成虫鉴别要点之一是：', '{"a":"前者有2对钩齿，后者有1对板齿","b":"前者无口囊，后者有吸盘","c":"前者为单细胞，后者为多细胞","d":"前者有包膜，后者无包膜"}'::jsonb, '"a"'::jsonb, '十二指肠钩虫口囊腹侧有2对钩齿，美洲钩虫口囊腹侧有1对板齿。', 12);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_43', 'parasite', 'nematodes', '蛲虫最主要的感染途径是：', '{"a":"肛门-手-口自身感染","b":"经皮肤钻入","c":"生食猪肉","d":"蚊虫叮咬"}'::jsonb, '"a"'::jsonb, '蛲虫雌虫夜间在肛周产卵，瘙痒抓挠后手污染，再经口摄入，是最主要的自身感染途径。', 13);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_44', 'parasite', 'nematodes', '蛲虫病的核心症状是：', '{"a":"夜间肛周瘙痒","b":"周期性寒战高热","c":"右上腹包块","d":"黑尿"}'::jsonb, '"a"'::jsonb, '雌虫夜间爬出肛门产卵刺激局部，引起夜间肛周瘙痒、湿疹和睡眠不安。', 14);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_45', 'parasite', 'nematodes', '蛲虫病诊断首选方法是：', '{"a":"肛门拭子法或透明胶纸法","b":"粪便直接涂片法","c":"肌肉活检","d":"骨髓穿刺"}'::jsonb, '"a"'::jsonb, '蛲虫不在肠内产卵，粪便检出率低，清晨排便前肛门拭子法或透明胶纸法最常用。', 15);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_46', 'parasite', 'nematodes', '蛲虫病防治中最重要的策略是：', '{"a":"卫生习惯、集体治疗和环境清洁","b":"只治疗出现腹痛者","c":"避免吃牛肉","d":"只喷洒灭蚊剂"}'::jsonb, '"a"'::jsonb, '蛲虫易在家庭和幼儿园反复传播，防治需个人卫生、环境清洁和家庭或集体同步治疗。', 16);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_47', 'parasite', 'nematodes', '旋毛虫病主要感染来源是：', '{"a":"生食或半生食含活幼虫囊包的肉类","b":"饮用含剑水蚤的生水","c":"蚊虫叮咬","d":"接触犬粪虫卵"}'::jsonb, '"a"'::jsonb, '旋毛虫病为动物源性食源性人畜共患病，人因食用含活幼虫囊包的猪肉或其他肉类感染。', 17);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_48', 'parasite', 'nematodes', '旋毛虫生活史中，人体既可作为：', '{"a":"终宿主又可作为中间宿主","b":"仅传播媒介","c":"仅保虫宿主","d":"完全不参与生活史"}'::jsonb, '"a"'::jsonb, '旋毛虫成虫在小肠，幼虫进入横纹肌形成囊包，同一宿主体内兼有成虫和幼虫阶段。', 18);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_49', 'parasite', 'nematodes', '旋毛虫病致病的核心阶段是：', '{"a":"幼虫移行期","b":"虫卵排出期","c":"卵囊成熟期","d":"节片脱落期"}'::jsonb, '"a"'::jsonb, '旋毛虫病以幼虫移行期损害为主，成虫致肠道炎症，幼虫可造成多器官损伤。', 19);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_50', 'parasite', 'nematodes', '旋毛虫病确诊金标准是：', '{"a":"肌肉活检见梭形囊包和卷曲幼虫","b":"肛周拭子见虫卵","c":"痰液查卵囊","d":"血膜见环状体"}'::jsonb, '"a"'::jsonb, '有生食肉史并在腓肠肌等肌肉活检中见梭形囊包及卷曲幼虫，可确诊旋毛虫病。', 20);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_51', 'parasite', 'nematodes', '预防旋毛虫病最关键的措施是：', '{"a":"不吃生或半生肉，肉类充分加热","b":"避免赤足下地","c":"防止水源被卵囊污染","d":"接种乙肝疫苗"}'::jsonb, '"a"'::jsonb, '旋毛虫病预防关键是不吃生或半生肉类，厨具生熟分开，肉类经充分高温或合规处理。', 21);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_52', 'parasite', 'nematodes', '下列哪组均属于常见肠道寄生线虫？', '{"a":"蛔虫、钩虫、蛲虫","b":"疟原虫、弓形虫、隐孢子虫","c":"猪带绦虫、牛带绦虫、棘球绦虫","d":"蚊、蝇、虱"}'::jsonb, '"a"'::jsonb, '材料列出的常见肠道寄生线虫包括蛔虫、钩虫和蛲虫；旋毛虫、丝虫等属于组织寄生线虫。', 22);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_53', 'parasite', 'nematodes', '钩虫幼虫导致的皮肤损害俗称：', '{"a":"粪毒","b":"米猪肉","c":"包虫砂","d":"四世同堂"}'::jsonb, '"a"'::jsonb, '钩虫丝状蚴钻入皮肤可引起钩蚴性皮炎，俗称粪毒，表现为奇痒、丘疹、疱疹或脓疱。', 23);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_54', 'parasite', 'nematodes', '线虫幼虫成熟通常需要蜕皮次数为：', '{"a":"1次","b":"2次","c":"4次","d":"8次"}'::jsonb, '"c"'::jsonb, '线虫生活史一般为虫卵、幼虫、成虫，幼虫需经过4次蜕皮成熟。', 24);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_55', 'parasite', 'nematodes', '蛔虫防治中属于切断传播途径的关键措施是：', '{"a":"粪便无害化处理","b":"捕杀病犬","c":"屠宰牛肉检查囊尾蚴","d":"治疗AIDS"}'::jsonb, '"a"'::jsonb, '蛔虫卵随粪便排出并污染土壤和食物，粪便无害化处理可切断传播途径。', 25);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_56', 'parasite', 'cestodes', '绦虫成虫的消化系统特点是：', '{"a":"完全退化，无口无肛无消化道","b":"有发达胃肠道","c":"仅有口无肛","d":"仅有肛无口"}'::jsonb, '"a"'::jsonb, '绦虫成虫消化系统完全退化，依靠体表微毛直接吸收宿主营养。', 1);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_57', 'parasite', 'cestodes', '绦虫头节的主要功能是：', '{"a":"固着于宿主组织","b":"产生虫卵","c":"吸收全部营养","d":"进行有性配子结合"}'::jsonb, '"a"'::jsonb, '头节是绦虫的固着器官，可有吸盘、吸槽、小钩等结构。', 2);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_58', 'parasite', 'cestodes', '假叶目绦虫生活史通常需要：', '{"a":"两个中间宿主且必须进入水体发育","b":"不需要任何宿主","c":"只在蚊体内发育","d":"只在人体内完成全部发育"}'::jsonb, '"a"'::jsonb, '材料指出假叶目绦虫需要两个中间宿主，且必须进入水体发育，类似吸虫。', 3);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_59', 'parasite', 'cestodes', '曼氏迭宫绦虫人体感染最主要的阶段和疾病是：', '{"a":"裂头蚴引起裂头蚴病","b":"囊尾蚴引起猪带绦虫病","c":"虫卵引起蛲虫病","d":"丝状蚴引起钩虫病"}'::jsonb, '"a"'::jsonb, '人主要感染曼氏迭宫绦虫幼虫阶段裂头蚴，可形成眼、皮下、口腔面部、脑等裂头蚴病。', 4);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_60', 'parasite', 'cestodes', '曼氏裂头蚴病最主要感染方式之一是：', '{"a":"用生蛙肉或蛇皮敷贴伤口或眼部","b":"被按蚊叮咬","c":"吸入空气中虫卵","d":"接触病犬皮毛"}'::jsonb, '"a"'::jsonb, '民间用生蛙肉、蛇皮敷贴伤口、眼部、口腔或外阴，可使裂头蚴经皮肤黏膜侵入，是重要感染方式。', 5);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_61', 'parasite', 'cestodes', '猪带绦虫成虫头节的典型结构是：', '{"a":"4个吸盘和顶突小钩","b":"两条吸槽无小钩","c":"无吸盘无小钩","d":"只有纤毛"}'::jsonb, '"a"'::jsonb, '链状带绦虫即猪带绦虫，又称有钩绦虫，头节有4个吸盘和顶突，顶突上有两圈小钩。', 6);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_62', 'parasite', 'cestodes', '猪带绦虫病的感染阶段是：', '{"a":"囊尾蚴","b":"虫卵","c":"卵囊","d":"丝状蚴"}'::jsonb, '"a"'::jsonb, '人食入生的或未熟的含囊尾蚴猪肉可患猪带绦虫病，囊尾蚴在小肠发育为成虫。', 7);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_63', 'parasite', 'cestodes', '猪囊尾蚴病的感染阶段是：', '{"a":"猪带绦虫虫卵","b":"牛囊尾蚴","c":"原尾蚴","d":"包虫砂"}'::jsonb, '"a"'::jsonb, '人误食猪带绦虫虫卵后可作为中间宿主，六钩蚴在人体组织中发育为囊尾蚴。', 8);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_64', 'parasite', 'cestodes', '猪带绦虫卵和牛带绦虫卵的镜下鉴别特点是：', '{"a":"形态相似，难以依虫卵鉴别","b":"猪带绦虫卵有三对足","c":"牛带绦虫卵有鞭毛","d":"二者颜色完全相反"}'::jsonb, '"a"'::jsonb, '带绦虫卵结构相似，光镜下不能作为虫种鉴别依据，需要结合节片、头节或病史等。', 9);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_65', 'parasite', 'cestodes', '牛带绦虫头节与猪带绦虫头节的重要区别是：', '{"a":"牛带绦虫无顶突和小钩","b":"牛带绦虫有两圈小钩","c":"牛带绦虫无吸盘","d":"牛带绦虫为单细胞"}'::jsonb, '"a"'::jsonb, '牛带绦虫头节有四个吸盘，但无顶突和小钩，因此又称无钩绦虫。', 10);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_66', 'parasite', 'cestodes', '牛带绦虫患者常有的提示性主诉是：', '{"a":"孕节主动从肛门溢出并引起不适","b":"周期性寒战高热","c":"夜间肛周产卵","d":"水样腹泻5-10L"}'::jsonb, '"a"'::jsonb, '牛带绦虫孕节活动性强，可主动从肛门溢出，患者常诉肛周瘙痒和不愉快感。', 11);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_67', 'parasite', 'cestodes', '细粒棘球绦虫的终宿主主要是：', '{"a":"犬、狼等犬科食肉动物","b":"人","c":"牛和羊","d":"按蚊"}'::jsonb, '"a"'::jsonb, '细粒棘球绦虫成虫主要寄生于犬、狼等犬科食肉动物小肠，人和牛羊等为中间宿主。', 12);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_68', 'parasite', 'cestodes', '棘球蚴病中人体感染的主要方式是：', '{"a":"摄入被虫卵污染的食物或水","b":"食入含囊尾蚴牛肉","c":"白蛉叮咬","d":"赤足接触土壤"}'::jsonb, '"a"'::jsonb, '人误食犬等终宿主粪便污染的虫卵后，六钩蚴经血循环到肝肺等器官发育为棘球蚴。', 13);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_69', 'parasite', 'cestodes', '棘球蚴病最常见寄生部位是：', '{"a":"肝脏","b":"红细胞","c":"肛周皮肤","d":"阴道后穹隆"}'::jsonb, '"a"'::jsonb, '棘球蚴病以肝脏最常见，约占70%，其次为肺部，也可累及脑、眼、脾、肾等。', 14);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_70', 'parasite', 'cestodes', '细粒棘球蚴手术治疗时最需避免的是：', '{"a":"囊液外溢","b":"使用无菌器械","c":"完整取出囊体","d":"术前影像定位"}'::jsonb, '"a"'::jsonb, '棘球蚴囊液富含抗原，外溢可引起过敏性休克并导致原头蚴播散形成继发感染。', 15);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_71', 'parasite', 'medical_arthropods', '医学节肢动物间接危害中最主要的是：', '{"a":"传播疾病","b":"产生维生素","c":"帮助消化","d":"提供免疫保护"}'::jsonb, '"a"'::jsonb, '节肢动物的间接危害是传播虫媒病，这是医学节肢动物最主要的危害方式。', 1);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_72', 'parasite', 'medical_arthropods', '昆虫纲成虫的基本身体分部是：', '{"a":"头、胸、腹三部分","b":"头胸部和腹部两部分","c":"头节、颈节、链体","d":"胞膜、胞质、胞核"}'::jsonb, '"a"'::jsonb, '昆虫纲虫体分为头、胸、腹三部分，头部有复眼和触角，胸部有三对足。', 2);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_73', 'parasite', 'medical_arthropods', '蛛形纲成虫的典型足数是：', '{"a":"三对足","b":"四对足","c":"五对足","d":"每节两对足"}'::jsonb, '"b"'::jsonb, '蛛形纲成虫有四对足，无触角，常见种类包括蜱、螨、蜘蛛、蝎等。', 3);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_74', 'parasite', 'medical_arthropods', '完全变态的发育阶段包括：', '{"a":"卵、幼虫、蛹、成虫","b":"卵、若虫、成虫","c":"滋养体、包囊","d":"头节、颈节、孕节"}'::jsonb, '"a"'::jsonb, '完全变态经历卵、幼虫、蛹、成虫四个阶段，蚊、蝇、白蛉等属于完全变态。', 4);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_75', 'parasite', 'medical_arthropods', '不完全变态的发育阶段包括：', '{"a":"卵、若虫、成虫","b":"卵、幼虫、蛹、成虫","c":"虫卵、幼虫、成虫、囊包","d":"包囊、滋养体、卵囊"}'::jsonb, '"a"'::jsonb, '不完全变态又称半变态，经历卵、若虫、成虫三个阶段，如虱和蜚蠊。', 5);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_76', 'parasite', 'medical_arthropods', '机械性传播的含义是：', '{"a":"病原体在节肢动物体内无形态或生物学变化","b":"病原体必须在媒介体内有性生殖","c":"只经胎盘传播","d":"只由药物注射传播"}'::jsonb, '"a"'::jsonb, '机械性传播中节肢动物只起携带和输送作用，病原体没有形态或生物学变化，如蝇传播痢疾、伤寒。', 6);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_77', 'parasite', 'medical_arthropods', '蚊的生活史特点是：', '{"a":"完全变态，前三个阶段生活在水中","b":"不完全变态，全部阶段陆生","c":"只有滋养体阶段","d":"只在犬体内发育"}'::jsonb, '"a"'::jsonb, '蚊为完全变态昆虫，卵、幼虫、蛹三个阶段生活在水中，成虫陆生。', 7);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_78', 'parasite', 'medical_arthropods', '不同蚊种滋生地匹配正确的是：', '{"a":"按蚊多在大面积清水","b":"库蚊多在树洞小型清水","c":"伊蚊多在污水沟","d":"所有蚊种只在海水繁殖"}'::jsonb, '"a"'::jsonb, '按蚊多孳生于稻田、湖塘、沼泽等大面积清水；库蚊偏污水，伊蚊偏小型清水容器。', 8);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_79', 'parasite', 'medical_arthropods', '蝇传播痢疾、伤寒主要属于：', '{"a":"机械性传播","b":"经卵传播","c":"垂直传播","d":"遗传传播"}'::jsonb, '"a"'::jsonb, '非吸血性蝇种可通过体表鬃毛、足、口器等携带病原体，机械性传播肠道传染病。', 9);
insert into public.quiz_questions (id, category_id, chapter_id, question, options, correct_answer, explanation, sort_order) values ('parasite_80', 'parasite', 'medical_arthropods', '体虱可传播的疾病是：', '{"a":"流行性斑疹伤寒","b":"包虫病","c":"蛔虫病","d":"水痘"}'::jsonb, '"a"'::jsonb, '虱寄生人体叮咬皮肤，可继发感染；体虱是流行性斑疹伤寒等疾病的重要传播媒介。', 10);
